Mutation = Callable[[Path, Path], None]
Archive = Callable[[Path], Path]


@dataclass(frozen=True)
class Case:
    name: str
    expect: str | None = None      # check id that must fire; None = the return must be spotless
    severity: str | None = None    # severity that finding must carry (required with `expect`)
    mutate: Mutation | None = None
    message: str | None = None     # substring the finding's message must carry (tells branches apart)
    with_vision: bool = True
    scope: str = "full-stack"
    archive: Archive | None = None  # hostile archive instead of a folder return
    forbid: str | None = None      # check id that must NOT fire


def _sub(path: Path, old: str, new: str) -> None:
    text = path.read_text(encoding="utf-8")
    if old not in text:
        raise AssertionError(f"self-test fixture drifted: «{old[:40]}» not found in {path.name}")
    path.write_text(text.replace(old, new, 1), encoding="utf-8")


def _write(path: Path, text: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text, encoding="utf-8")


def _feat(ret: Path, name: str) -> Path:
    return ret / "FEAT-999" / name


def _vis(ret: Path, name: str) -> Path:
    return ret / "VISION" / name


def _only_vision(_repo: Path, ret: Path) -> None:
    shutil.rmtree(ret / "FEAT-999")
    head = (ret / "MANIFEST.yaml").read_text(encoding="utf-8").split("features:", 1)[0]
    _write(ret / "MANIFEST.yaml", head + "features: []\n")


def _strip_tokens(_repo: Path, ret: Path) -> None:
    import re
    for name in ("style_guide.html", "app_shell.html"):
        page = _vis(ret, name)
        _write(page, re.sub(r"<style>.*?</style>", "", page.read_text(encoding="utf-8"), flags=re.S))


def _scope_from_repo(repo: Path, ret: Path) -> None:
    """No scope in the ERQ, no mock: the scope must come from the journey already in the repo."""
    _sub(_feat(ret, "ERQ.md"), 'scope: "backend-only"\n', "")
    _write(repo / "docs" / "spec" / "FEAT-999" / "user_journey.md", F.journey("FEAT-999", "backend-only", True))


def _tailwind_tokens(_repo: Path, ret: Path) -> None:
    """Tokens declared the way the framework's own templates do it: no root CSS block at all."""
    _strip_tokens(_repo, ret)
    _sub(_vis(ret, "app_shell.html"), "</head>", "<script>tailwind.config = {theme: {extend: {}}}</script></head>")


def _with_header(scope: str, drop_erq_scope: bool = False) -> Mutation:
    """The PO evolves an existing feature from the shipped annex, which carries the factory header."""
    def mutate(_repo: Path, ret: Path) -> None:
        if drop_erq_scope:
            _sub(_feat(ret, "ERQ.md"), f'scope: "{scope}"\n', "")
        page = _feat(ret, "user_journey.md")
        _write(page, F.JOURNEY_FRONTMATTER.format(fid="FEAT-999", scope=scope) + page.read_text(encoding="utf-8"))
    return mutate


def _mock_head(markup: str) -> Mutation:
    return lambda _repo, ret: _sub(_feat(ret, "mock.html"), "<style>", markup + "<style>")


def _only_vision_no_manifest(repo: Path, ret: Path) -> None:
    _only_vision(repo, ret)
    (ret / "MANIFEST.yaml").unlink()


def _gate(body: str) -> Mutation:
    return lambda repo, _ret: _write(repo / "scripts" / "check-journey-grammar.sh", body)


